<script lang="ts">
  import { api, type Assurance, type Contract, type GitHubPR, type PatchResult, type Repository } from '$lib/api/client';
  type Stage='inputs'|'analysis'|'patches';
  let stage=$state<Stage>('inputs'); let oldContract=$state<Contract|null>(null); let newContract=$state<Contract|null>(null); let repo=$state<Repository|null>(null); let result=$state<Assurance|null>(null); let patchResult=$state<PatchResult|null>(null);
  let loading=$state(''); let error=$state(''); let allowExecution=$state(false); let approved=$state<string[]>([]); let selectedChange=$state<string>('');
  let githubOwner=$state(''); let githubRepo=$state(''); let githubBase=$state('main'); let githubBranch=$state(''); let githubPR=$state<GitHubPR|null>(null);

  async function uploadContract(event:Event,kind:'old'|'new'){const input=event.currentTarget as HTMLInputElement;const file=input.files?.[0];if(!file)return;loading=kind;error='';try{const value=await api.uploadContract(file);if(kind==='old')oldContract=value;else newContract=value;}catch(e){error=e instanceof Error?e.message:'Upload failed';}finally{loading='';input.value='';}}
  async function uploadRepo(event:Event){const input=event.currentTarget as HTMLInputElement;const file=input.files?.[0];if(!file)return;loading='repo';error='';try{repo=await api.uploadRepository(file);}catch(e){error=e instanceof Error?e.message:'Upload failed';}finally{loading='';input.value='';}}
  async function analyze(){if(!oldContract||!newContract||!repo)return;loading='analysis';error='';try{result=await api.analyze(oldContract.contract_id,newContract.contract_id,repo.repository_id,allowExecution);approved=result.patch_plan.filter(p=>p.confidence==='high'&&p.kind!=='manual').map(p=>p.id);selectedChange=result.changes.find(c=>c.severity==='breaking')?.id??result.changes[0]?.id??'';stage='analysis';}catch(e){error=e instanceof Error?e.message:'Analysis failed';}finally{loading='';}}
  function togglePatch(id:string){approved=approved.includes(id)?approved.filter(x=>x!==id):[...approved,id];}
  async function applyPatches(){if(!result||!approved.length)return;loading='patch';error='';try{patchResult=await api.apply(result.analysis_id,approved);stage='patches';}catch(e){error=e instanceof Error?e.message:'Patch application failed';}finally{loading='';}}
  async function publishPR(){if(!result||!approved.length||!githubOwner.trim()||!githubRepo.trim())return;loading='github';error='';try{githubPR=await api.publishGitHubPR(result.analysis_id,{owner:githubOwner.trim(),repo:githubRepo.trim(),base_branch:githubBase.trim()||'main',branch_name:githubBranch.trim(),title:`API evolution migration · ${result.analysis_id}`,body:'',approved_patch_ids:approved});}catch(e){error=e instanceof Error?e.message:'GitHub PR creation failed';}finally{loading='';}}
  const activeChange=$derived(result?.changes.find(c=>c.id===selectedChange)??null);
</script>
<svelte:head><title>API Evolution Assurance</title></svelte:head>
<main class="shell">
  <aside class="rail">
    <div class="brand"><span>∆</span><div><strong>APIEvolve</strong><small>evolution assurance</small></div></div>
    <nav><button class:active={stage==='inputs'} onclick={()=>stage='inputs'}>01 · Contracts</button><button class:active={stage==='analysis'} disabled={!result} onclick={()=>stage='analysis'}>02 · Blast radius</button><button class:active={stage==='patches'} disabled={!patchResult} onclick={()=>stage='patches'}>03 · Patch artifact</button></nav>
    <div class="safety"><i></i><div><strong>Repository execution is OFF by default.</strong><span>Static analysis never implies permission to run uploaded code.</span></div></div>
  </aside>
  <section class="workspace">
    <header class="hero"><div><p>Semantic contract diff · repository usage graph · migration evidence</p><h1>Know what an API change breaks before your customers discover it in production.</h1></div><button class="primary" onclick={analyze} disabled={!oldContract||!newContract||!repo||!!loading}>{loading==='analysis'?'Analyzing…':'Run assurance'}</button></header>
    {#if error}<p class="error">{error}</p>{/if}

    {#if stage==='inputs'}
      <section class="input-grid">
        <article class="panel upload"><div class="ordinal">01</div><div><span>Baseline</span><h2>Old API contract</h2><p>OpenAPI / Swagger JSON or YAML. Local `$ref` schemas are resolved into the canonical model.</p></div>{#if oldContract}<div class="ready"><strong>{oldContract.title}</strong><small>{oldContract.openapi_version} · {oldContract.operation_count} operations · {oldContract.sha256.slice(0,10)}</small></div>{/if}<label for="old">{loading==='old'?'Parsing…':'Choose contract'}</label><input id="old" type="file" accept=".json,.yaml,.yml" onchange={(e)=>uploadContract(e,'old')}/></article>
        <article class="panel upload"><div class="ordinal">02</div><div><span>Candidate</span><h2>New API contract</h2><p>Compared semantically for path, parameters, request/response schemas, status codes and security requirements.</p></div>{#if newContract}<div class="ready"><strong>{newContract.title}</strong><small>{newContract.openapi_version} · {newContract.operation_count} operations · {newContract.sha256.slice(0,10)}</small></div>{/if}<label for="new">{loading==='new'?'Parsing…':'Choose contract'}</label><input id="new" type="file" accept=".json,.yaml,.yml" onchange={(e)=>uploadContract(e,'new')}/></article>
        <article class="panel upload"><div class="ordinal">03</div><div><span>Consumer</span><h2>Customer repository ZIP</h2><p>Python AST plus JS/TS/Svelte structural indexing maps calls, field accesses and import propagation without executing the repository.</p></div>{#if repo}<div class="ready"><strong>{repo.filename}</strong><small>{repo.file_count} files · {repo.network_call_count} calls · {repo.import_edge_count} import edges</small></div>{/if}<label for="repo">{loading==='repo'?'Indexing…':'Choose repository'}</label><input id="repo" type="file" accept=".zip" onchange={uploadRepo}/></article>
      </section>
      <article class="panel execution"><div><strong>Trusted validation runner</strong><p>When enabled, the backend may run detected lint/type/test/build commands only if the deployment also sets <code>AEA_ALLOW_LOCAL_EXECUTION=1</code>. Production deployments should provide an isolated sandbox runner.</p></div><label class="switch"><input type="checkbox" bind:checked={allowExecution}/><span></span><b>{allowExecution?'requested':'static only'}</b></label></article>
    {/if}

    {#if stage==='analysis' && result}
      <section class="results">
        <article class={`gate panel ${result.release_gate}`}><div><span>Release gate</span><h2>{result.release_gate.replaceAll('_',' ')}</h2>{#each result.release_gate_reasons as reason}<p>{reason}</p>{/each}</div><div class="stats"><div><strong>{result.breaking_change_count}</strong><span>breaking</span></div><div><strong>{result.usage_impacts.filter(i=>i.match_type!=='dependency_propagation').length}</strong><span>direct usages</span></div><div><strong>{result.patch_plan.length}</strong><span>patch ops</span></div></div></article>
        <section class="analysis-grid">
          <article class="panel changes"><div class="panel-title"><div><span>Contract evolution</span><h2>{result.changes.length} semantic changes</h2></div></div><div class="change-list">{#each result.changes as c}<button class:selected={selectedChange===c.id} onclick={()=>selectedChange=c.id}><i class={c.severity}></i><div><strong>{c.summary}</strong><small>{c.operation_key} · {c.category}</small></div><b>{c.severity.replaceAll('_',' ')}</b></button>{/each}</div></article>
          <aside class="stack">
            <article class="panel detail">{#if activeChange}<span>Selected change</span><h2>{activeChange.summary}</h2><div class="pill-row"><b>{activeChange.severity}</b><b>{activeChange.confidence} confidence</b></div><p>{activeChange.migration_hint}</p><pre>{JSON.stringify({old:activeChange.old,new:activeChange.new},null,2)}</pre>{/if}</article>
            <article class="panel"><div class="panel-title"><div><span>Validation policy</span><h2>Tool gates</h2></div></div>{#each result.validation as v}<div class="tool"><div><strong>{v.tool_id}</strong><small>{v.command.join(' ')||'built-in static gate'}</small></div><b class={v.status}>{v.status}</b></div>{/each}</article>
          </aside>
        </section>
        <section class="analysis-grid wide-left">
          <article class="panel"><div class="panel-title"><div><span>Repository impact</span><h2>Blast-radius graph projection</h2></div><small>{result.impacted_files.length} files</small></div><div class="files">{#each result.impacted_files as f}<article><div><strong>{f.file}</strong><small>{f.propagated_distance===0?'direct API usage':`dependency distance ${f.propagated_distance}`}</small></div><b>{f.direct_impacts}</b>{#each f.reasons.slice(0,2) as r}<p>{r}</p>{/each}</article>{/each}{#if result.impacted_files.length===0}<p class="empty">No affected usage was proven in the indexed repository. Dynamic/generated calls may still require review.</p>{/if}</div></article>
          <aside class="panel patches"><div class="panel-title"><div><span>Migration plan</span><h2>Human-approved patch operations</h2></div><button class="primary mini" onclick={applyPatches} disabled={!approved.length||!!loading}>{loading==='patch'?'Applying…':`Apply ${approved.length}`}</button></div>{#each result.patch_plan as p}<label class="patch"><input type="checkbox" checked={approved.includes(p.id)} onchange={()=>togglePatch(p.id)}/><div><strong>{p.file}:{p.line??'?'}</strong><small>{p.kind} · {p.confidence}</small><p>{p.reason}</p>{#if p.old_text&&p.new_text}<code>{p.old_text} → {p.new_text}</code>{/if}</div></label>{/each}{#if result.patch_plan.length===0}<p class="empty">No deterministic patch candidate was generated. Manual migration may still be required.</p>{/if}</aside>
        </section>
      </section>
    {/if}

    {#if stage==='patches' && patchResult}
      <section class="patch-result">
        <article class="panel artifact"><div><span>Patch artifact</span><h2>{patchResult.applied} applied · {patchResult.skipped} skipped</h2><p>Only explicitly approved exact replacements were applied. The artifact includes the patched repository and <code>API_EVOLUTION_PATCH.diff</code>.</p></div><a class="primary" href={api.artifactUrl(patchResult.download_path)}>Download patched repository</a></article>
        <section class="analysis-grid"><article class="panel"><div class="panel-title"><div><span>Patch outcomes</span><h2>Application trace</h2></div></div>{#each patchResult.outcomes as o}<div class="outcome"><b class={o.status}>{o.status}</b><strong>{o.patch_id}</strong><span>{o.detail}</span></div>{/each}</article><aside class="panel"><div class="panel-title"><div><span>Unified diff</span><h2>Review before PR</h2></div></div><pre class="diff">{patchResult.unified_diff||'No textual changes were applied.'}</pre></aside></section>
        <article class="panel github"><div><span>Optional GitHub publication</span><h2>Open a review branch + pull request</h2><p>The GitHub token stays server-side. Publishing re-applies only the currently approved deterministic patch IDs and requires explicit human approval.</p></div><div class="github-fields"><input aria-label="GitHub owner" placeholder="owner" bind:value={githubOwner}/><input aria-label="GitHub repository" placeholder="repository" bind:value={githubRepo}/><input aria-label="Base branch" placeholder="main" bind:value={githubBase}/><input aria-label="Migration branch" placeholder="api-evolution/analysis-id (auto)" bind:value={githubBranch}/><button class="primary" onclick={publishPR} disabled={!githubOwner.trim()||!githubRepo.trim()||!approved.length||!!loading}>{loading==='github'?'Publishing…':'Create GitHub PR'}</button></div>{#if githubPR}<a class="pr-link" href={githubPR.pull_url} target="_blank" rel="noreferrer">PR #{githubPR.pull_number} · {githubPR.branch_name} · {githubPR.commit_sha.slice(0,10)}</a>{/if}</article>
      </section>
    {/if}
  </section>
</main>

<style>
:global(body){margin:0;background:#f3f5f7;color:#12161b;font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;font-size:14px}.shell{min-height:100vh;display:grid;grid-template-columns:242px minmax(0,1fr)}.rail{position:sticky;top:0;height:100vh;box-sizing:border-box;background:#111820;color:#eff6fa;padding:22px 16px;display:flex;flex-direction:column;gap:28px}.brand{display:flex;align-items:center;gap:11px}.brand>span{display:grid;place-items:center;width:34px;height:34px;border-radius:10px;background:#7dd3fc;color:#0f1920;font-weight:900}.brand div{display:grid}.brand small{font-size:10px;color:#80909c}nav{display:grid;gap:6px}nav button{border:0;background:transparent;color:#81919d;text-align:left;border-radius:11px;padding:10px 11px;cursor:pointer}nav button.active,nav button:hover{background:#1c2832;color:white}nav button:disabled{opacity:.35}.safety{margin-top:auto;border:1px solid #2d3a45;background:#17212a;border-radius:16px;padding:13px;display:flex;gap:9px}.safety i{width:8px;height:8px;background:#7dd3fc;border-radius:50%;margin-top:4px}.safety div{display:grid;gap:4px}.safety strong{font-size:11px}.safety span{font-size:10px;color:#84949f;line-height:1.4}.workspace{padding:25px 30px 50px;min-width:0}.hero{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;margin-bottom:20px}.hero p,.panel-title span,.detail>span,.gate>div>span,.artifact>div>span{margin:0 0 7px;text-transform:uppercase;letter-spacing:.13em;color:#277da1;font-size:10px;font-weight:800}.hero h1{margin:0;max-width:850px;font-size:31px;line-height:1.03;letter-spacing:-.045em}.primary{border:0;border-radius:999px;background:#63c8ee;color:#0d1a21;padding:10px 14px;font:inherit;font-weight:800;cursor:pointer}.primary:disabled{opacity:.4}.error{background:#fff0eb;border:1px solid #efb7a4;color:#94361c;border-radius:13px;padding:10px}.input-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.panel{background:#fff;border:1px solid #dfe5e8;border-radius:20px;padding:17px;box-shadow:0 18px 60px rgba(22,40,52,.045)}.upload{display:grid;gap:14px;align-content:start;min-height:300px}.ordinal{width:30px;height:30px;display:grid;place-items:center;border-radius:9px;background:#eaf7fc;color:#277da1;font-size:10px;font-weight:900}.upload span{font-size:9px;text-transform:uppercase;letter-spacing:.12em;color:#75848e}.upload h2{margin:4px 0 7px;font-size:17px}.upload p,.execution p,.gate p,.detail p,.artifact p{font-size:11px;line-height:1.5;color:#68757e;margin:0}.upload label{margin-top:auto;background:#111820;color:white;border-radius:999px;text-align:center;padding:9px 12px;cursor:pointer}.upload input{position:absolute;opacity:0;pointer-events:none;width:1px}.ready{display:grid;border:1px solid #cce8f3;background:#f3fbfe;border-radius:13px;padding:10px}.ready strong{font-size:12px}.ready small{font-size:9px;color:#65808d;margin-top:4px}.execution{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-top:14px}.execution div{max-width:850px}.execution code{font-size:10px}.switch{display:flex;align-items:center;gap:8px;cursor:pointer}.switch input{display:none}.switch span{width:34px;height:18px;border-radius:999px;background:#ccd4d9;position:relative}.switch span:after{content:"";position:absolute;width:14px;height:14px;border-radius:50%;background:white;top:2px;left:2px;transition:.15s}.switch input:checked+span{background:#4cbde8}.switch input:checked+span:after{left:18px}.switch b{font-size:10px}.results,.stack,.patch-result{display:grid;gap:14px}.gate{display:flex;justify-content:space-between;align-items:center;gap:20px;background:#17232c;color:white;border-color:#17232c}.gate h2{margin:0 0 7px;font-size:26px;letter-spacing:-.04em}.gate p{color:#9facb5;margin-top:4px}.gate.blocked{box-shadow:inset 5px 0 #f38a6b}.gate.review_required{box-shadow:inset 5px 0 #f2c45d}.gate.pass{box-shadow:inset 5px 0 #7fd39a}.stats{display:flex;gap:24px}.stats div{display:grid;text-align:center}.stats strong{font-size:30px}.stats span{font-size:9px;text-transform:uppercase;color:#8f9ea8}.analysis-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(350px,.75fr);gap:14px}.analysis-grid.wide-left{grid-template-columns:minmax(0,1.2fr) minmax(400px,.9fr)}.panel-title{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:12px}.panel-title h2,.detail h2{margin:0;font-size:16px;letter-spacing:-.02em}.panel-title small{font-size:9px;color:#7f8c95}.change-list{display:grid;gap:7px;max-height:620px;overflow:auto}.change-list button{display:grid;grid-template-columns:8px 1fr auto;gap:10px;align-items:center;text-align:left;border:1px solid #e2e7ea;background:#fbfcfd;border-radius:13px;padding:10px;cursor:pointer;color:#151a1e}.change-list button.selected{background:#14202a;color:white;border-color:#14202a}.change-list i{width:7px;height:34px;border-radius:99px;background:#aeb9bf}.change-list i.breaking{background:#ee7655}.change-list i.potentially_breaking{background:#e4b84f}.change-list i.non_breaking{background:#70c78f}.change-list div{display:grid;gap:3px}.change-list strong{font-size:11px}.change-list small{font-size:9px;color:#7d8990}.change-list button.selected small{color:#91a0a9}.change-list b{font-size:8px;text-transform:uppercase}.pill-row{display:flex;gap:6px;margin:9px 0}.pill-row b{font-size:8px;text-transform:uppercase;background:#ecf3f6;border-radius:999px;padding:5px 7px}.detail pre,pre.diff{background:#101920;color:#d8e3e8;border-radius:12px;padding:10px;max-height:250px;overflow:auto;font-size:10px;white-space:pre-wrap}.tool{display:flex;justify-content:space-between;gap:10px;align-items:center;border-top:1px solid #e5e9eb;padding:9px 0}.tool:first-of-type{border-top:0}.tool div{display:grid}.tool strong{font-size:11px}.tool small{font-size:9px;color:#7c8991}.tool>b,.outcome>b{font-size:8px;text-transform:uppercase;border-radius:999px;background:#edf1f3;padding:5px 7px}.tool>b.passed,.outcome>b.applied{background:#e2f5e8;color:#37744c}.tool>b.failed,.tool>b.timeout,.outcome>b.failed{background:#f9e3dd;color:#8d3a23}.tool>b.skipped,.outcome>b.skipped{background:#f7f0dc;color:#86691d}.files{display:grid;gap:7px}.files article{display:grid;grid-template-columns:1fr auto;gap:5px 12px;border:1px solid #e1e6e9;background:#fbfcfd;border-radius:13px;padding:10px}.files div{display:grid}.files strong{font-size:11px}.files small{font-size:9px;color:#7b8991}.files>b{font-size:18px;color:#287ea2}.files p{grid-column:1/-1;margin:0;font-size:9px;color:#68757d}.patches{align-self:start}.mini{padding:6px 10px;font-size:10px}.patch{display:grid;grid-template-columns:auto 1fr;gap:9px;border-top:1px solid #e3e8ea;padding:10px 0;cursor:pointer}.patch:first-of-type{border-top:0}.patch input{margin-top:3px}.patch div{display:grid}.patch strong{font-size:11px}.patch small{font-size:9px;color:#7c8990}.patch p{margin:5px 0;font-size:9px;line-height:1.4;color:#66747c}.patch code{font-size:9px;background:#edf3f6;border-radius:7px;padding:5px}.empty{font-size:10px;color:#7c8990}.artifact{display:flex;justify-content:space-between;align-items:center;gap:20px;background:#14212a;color:white;border-color:#14212a}.artifact h2{font-size:25px;margin:0 0 7px}.artifact p{color:#9baab3}.artifact .primary{text-decoration:none;white-space:nowrap}.outcome{display:grid;grid-template-columns:auto auto 1fr;gap:9px;align-items:center;border-top:1px solid #e3e8ea;padding:10px 0}.outcome:first-of-type{border-top:0}.outcome strong{font-size:10px}.outcome span{font-size:10px;color:#68757d}pre.diff{max-height:600px}.github{display:grid;grid-template-columns:minmax(0,.7fr) minmax(520px,1.3fr);gap:20px;align-items:end}.github>div:first-child>span{margin:0 0 7px;text-transform:uppercase;letter-spacing:.13em;color:#277da1;font-size:10px;font-weight:800}.github h2{margin:0 0 7px;font-size:17px}.github p{margin:0;font-size:10px;line-height:1.5;color:#68757e}.github-fields{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.github-fields input{border:1px solid #dce3e7;border-radius:11px;padding:9px 10px;font:inherit;font-size:10px;background:#fbfcfd}.github-fields .primary{grid-column:1/-1}.pr-link{grid-column:1/-1;color:#277da1;font-size:10px;font-weight:800;text-decoration:none;background:#eef9fd;border:1px solid #cdebf6;border-radius:11px;padding:9px 10px}@media(max-width:1120px){.shell{grid-template-columns:1fr}.rail{position:static;height:auto}.input-grid,.analysis-grid,.analysis-grid.wide-left{grid-template-columns:1fr}.hero{display:grid}.gate,.artifact,.github{display:grid;grid-template-columns:1fr}.github-fields{grid-template-columns:1fr}}@media(max-width:650px){.workspace{padding:18px}.stats{gap:12px;flex-wrap:wrap}.execution{display:grid}}
</style>
